local DiceMaker = {}
local PRODUCTS = {
    dice = { name = "Kocka", woodCost = 1, time = 1, cost = 5, happiness = 2, description = "Preproste lesene kocke." },
    bone_dice = { name = "Kostene kocke", boneCost = 1, time = 2, cost = 15, happiness = 3, description = "Kocke iz kosti." },
    chess_set = { name = "Šah", woodCost = 5, time = 10, cost = 100, happiness = 8, prestige = 5, knowledge = 5, description = "Šahovska garnitura." },
    backgammon = { name = "Tavla", woodCost = 3, boneCost = 2, time = 7, cost = 60, happiness = 6, description = "Igra tavla." },
    playing_cards = { name = "Igralne karte", parchmentCost = 3, inkCost = 1, time = 3, cost = 20, happiness = 5, description = "Ročno poslikane karte." },
    board_game = { name = "Tablična igra", woodCost = 4, paintCost = 1, time = 8, cost = 80, happiness = 7, prestige = 3, description = "Igra na deski." },
}
local BUILDINGS = {
    workshop = { name = "Igrarska delavnica", cost = { gold = 200, wood = 100 }, upkeep = 5, qualityBonus = 5 },
    toy_shop = { name = "Igračarna", cost = { gold = 500, wood = 200, stone = 100 }, upkeep = 12, qualityBonus = 15, happiness = 3 },
    game_studio = { name = "Igrarski atelje", cost = { gold = 1500, wood = 300, stone = 300 }, upkeep = 30, qualityBonus = 25, prestigeBonus = 5 },
    royal_toymaker = { name = "Kraljevski igračar", cost = { gold = 3000, wood = 400, stone = 600 }, upkeep = 60, qualityBonus = 35, prestigeBonus = 15 },
}
DiceMaker.woodStock = 15; DiceMaker.boneStock = 5; DiceMaker.parchmentStock = 8; DiceMaker.inkStock = 5; DiceMaker.paintStock = 3
DiceMaker.productStock = {}; DiceMaker.buildings = {}; DiceMaker.maker = nil; DiceMaker.activeMaking = {}; DiceMaker.totalProducts = 0; DiceMaker.dayTimer = 0
function DiceMaker.init() DiceMaker.woodStock=15; DiceMaker.boneStock=5; DiceMaker.parchmentStock=8; DiceMaker.inkStock=5; DiceMaker.paintStock=3; DiceMaker.productStock={}; DiceMaker.buildings={}; DiceMaker.maker=nil; DiceMaker.activeMaking={}; DiceMaker.totalProducts=0; DiceMaker.dayTimer=0; print("[DiceMaker] Royal Dice & Game Maker System initialized (6 products, 4 buildings)") end
function DiceMaker.hireMaker(n,s) s=s or math.random(35,80); local c=250+s*5; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; DiceMaker.maker={name=n or ("Igračar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Igračar najet: %s (spretnost: %d)",DiceMaker.maker.name,s),"success") end; return true end
function DiceMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function DiceMaker.build(id) local ok,e=DiceMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(DiceMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function DiceMaker.getQualityBonus() local b=0; for _,bd in ipairs(DiceMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function DiceMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and DiceMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.boneCost and DiceMaker.boneStock<(d.boneCost or 0) then return false,"Premalo kosti" end; if d.parchmentCost and DiceMaker.parchmentStock<(d.parchmentCost or 0) then return false,"Premalo pergamenta" end; if d.inkCost and DiceMaker.inkStock<(d.inkCost or 0) then return false,"Premalo črnila" end; if d.paintCost and DiceMaker.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if #DiceMaker.buildings==0 then return false,"Potrebna delavnica" end; if not DiceMaker.maker then return false,"Potreben igračar" end; return true end
function DiceMaker.make(pt) local ok,e=DiceMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then DiceMaker.woodStock=DiceMaker.woodStock-d.woodCost end; if d.boneCost then DiceMaker.boneStock=DiceMaker.boneStock-d.boneCost end; if d.parchmentCost then DiceMaker.parchmentStock=DiceMaker.parchmentStock-d.parchmentCost end; if d.inkCost then DiceMaker.inkStock=DiceMaker.inkStock-d.inkCost end; if d.paintCost then DiceMaker.paintStock=DiceMaker.paintStock-d.paintCost end; local t=d.time; if DiceMaker.maker then t=math.max(1,t-math.floor(DiceMaker.maker.skill/15)) end; table.insert(DiceMaker.activeMaking,{id="game_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost,happiness=d.happiness or 0,prestige=d.prestige or 0,knowledge=d.knowledge or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %s (%d dni)",d.name,t),"info") end; return true end
function DiceMaker.completeMaking(m) local q=1.0+(DiceMaker.getQualityBonus()/100); if DiceMaker.maker then q=q+(DiceMaker.maker.skill/200) end; q=math.min(2.0,q); DiceMaker.productStock[m.productType]=(DiceMaker.productStock[m.productType] or 0)+1; DiceMaker.totalProducts=DiceMaker.totalProducts+1; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness*q) end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.knowledge>0 and _G.Culture then pcall(function() _G.Culture.knowledgePoints=(_G.Culture.knowledgePoints or 0)+m.knowledge end) end; if DiceMaker.maker then DiceMaker.maker.itemsMade=DiceMaker.maker.itemsMade+1; if math.random()<0.15 then DiceMaker.maker.skill=math.min(100,DiceMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Igra izdelana: %s (kakovost: %.1f)",m.productName,q),"success") end end
function DiceMaker.update(dt) if not _G.state then return end; DiceMaker.dayTimer=DiceMaker.dayTimer+dt; if DiceMaker.dayTimer>=30 then DiceMaker.dayTimer=0; for i=#DiceMaker.activeMaking,1,-1 do local m=DiceMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then DiceMaker.completeMaking(m); table.remove(DiceMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(DiceMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if DiceMaker.maker then tu=tu+8 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function DiceMaker.getStats() return {woodStock=DiceMaker.woodStock,boneStock=DiceMaker.boneStock,productStock=DiceMaker.productStock,numBuildings=#DiceMaker.buildings,hasMaker=DiceMaker.maker~=nil,makerName=DiceMaker.maker and DiceMaker.maker.name or "—",makerSkill=DiceMaker.maker and DiceMaker.maker.skill or 0,activeMaking=#DiceMaker.activeMaking,totalProducts=DiceMaker.totalProducts} end
return DiceMaker
